"""Minimal, privacy-conscious client for OpenAI's Responses API.

The module uses only Python's standard library. Set ``OPENAI_API_KEY`` and
call ``send_prompt()``, or pipe a prompt to this file on standard input.
"""

from __future__ import annotations

import json
import os
import sys
from typing import Any
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


RESPONSES_URL = "https://api.openai.com/v1/responses"


class OpenAIError(RuntimeError):
    """Raised when the Responses API request cannot be completed."""


def _error_message(body: bytes, status: int) -> str:
    """Return an API error without including the submitted prompt."""
    try:
        payload = json.loads(body.decode("utf-8"))
        message = payload.get("error", {}).get("message")
        if isinstance(message, str) and message:
            return f"OpenAI API error {status}: {message}"
    except (UnicodeDecodeError, json.JSONDecodeError, AttributeError):
        pass
    return f"OpenAI API error {status}"


def _output_text(response: dict[str, Any]) -> str:
    """Extract concatenated text from a Responses API response."""
    direct = response.get("output_text")
    if isinstance(direct, str):
        return direct

    parts: list[str] = []
    for item in response.get("output", []):
        if not isinstance(item, dict) or item.get("type") != "message":
            continue
        for content in item.get("content", []):
            if not isinstance(content, dict):
                continue
            if content.get("type") == "output_text" and isinstance(
                content.get("text"), str
            ):
                parts.append(content["text"])
    if not parts:
        raise OpenAIError("The API response contained no text output")
    return "".join(parts)


def send_prompt(
    prompt: str,
    *,
    model: str = "gpt-5",
    api_key: str | None = None,
    timeout: float = 60.0,
) -> str:
    """Send a private text prompt and return the response text.

    Requests explicitly disable server-side response storage. The API key is
    read from ``OPENAI_API_KEY`` unless supplied directly and is never logged.
    """
    if not isinstance(prompt, str) or not prompt:
        raise ValueError("prompt must be a non-empty string")
    if not isinstance(model, str) or not model:
        raise ValueError("model must be a non-empty string")

    key = api_key or os.environ.get("OPENAI_API_KEY")
    if not key:
        raise OpenAIError("Set OPENAI_API_KEY before sending a prompt")

    body = json.dumps(
        {"model": model, "input": prompt, "store": False},
        ensure_ascii=False,
    ).encode("utf-8")
    headers = {
        "Authorization": f"Bearer {key}",
        "Content-Type": "application/json",
    }
    if os.environ.get("OPENAI_ORGANIZATION"):
        headers["OpenAI-Organization"] = os.environ["OPENAI_ORGANIZATION"]
    if os.environ.get("OPENAI_PROJECT"):
        headers["OpenAI-Project"] = os.environ["OPENAI_PROJECT"]

    request = Request(RESPONSES_URL, data=body, headers=headers, method="POST")
    try:
        with urlopen(request, timeout=timeout) as result:
            response = json.load(result)
    except HTTPError as exc:
        raise OpenAIError(_error_message(exc.read(), exc.code)) from None
    except URLError as exc:
        raise OpenAIError(f"Could not reach OpenAI: {exc.reason}") from None
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise OpenAIError("OpenAI returned an invalid JSON response") from exc

    if not isinstance(response, dict):
        raise OpenAIError("OpenAI returned an unexpected response")
    return _output_text(response)


def main() -> int:
    """Read a prompt from stdin so it does not appear in process arguments."""
    prompt = sys.stdin.read()
    if not prompt:
        print("Provide a prompt on standard input.", file=sys.stderr)
        return 2
    try:
        print(send_prompt(prompt.rstrip("\n")))
    except (OpenAIError, ValueError) as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
